const C=()=>{try{return root.TravelCore?.cruise;}catch{return false;}};
function tAA(x){x=x.trim();if(!x)return '';return ' '+x.replace(/Live-Abruf gerade offline/,'Live lookup offline right now').replace(/Live-Abruf vom Browser blockiert/,'Live lookup blocked by the browser').replace(/Live-Abruf keine Antwort/,'Live lookup: no response').replace(/Live-Abruf Fehler: /,'Live lookup error: ').replace(/ – es gilt der zuletzt abgerufene Stand\./,' – the last fetched data applies.');}
function tCount(s){return s.replace(/^(\d+) (neue Station|neue Stationen)$/,(m,n)=>`${n} new ${n==='1'?'stop':'stops'}`).replace(/^(\d+) (Änderung|Änderungen) an Route oder Einstellungen$/,(m,n)=>`${n} ${n==='1'?'change':'changes'} to route or settings`).replace(/^(\d+) (gelöschte Station|gelöschte Stationen)$/,(m,n)=>`${n} deleted ${n==='1'?'stop':'stops'}`).replace(/^(\d+) (neuer Tagebucheintrag|neue Tagebucheinträge)$/,(m,n)=>`${n} new diary ${n==='1'?'entry':'entries'}`).replace(/^(\d+) (geänderter Tagebucheintrag|geänderte Tagebucheinträge)$/,(m,n)=>`${n} changed diary ${n==='1'?'entry':'entries'}`).replace(/^(\d+) (gelöschter Tagebucheintrag|gelöschte Tagebucheinträge)$/,(m,n)=>`${n} deleted diary ${n==='1'?'entry':'entries'}`);}
/* Bausteine innerhalb längerer Texte (z. B. Vertretungsnamen, Zeilen mit „ · “) */
const PHRASES=[['Deutsche Botschaft','German Embassy'],['Deutsches Konsulat','German Consulate'],['Generalkonsulat','Consulate General'],['Honorarkonsulin','Honorary Consul'],['Honorarkonsul','Honorary Consul'],['(zuständig)','(responsible)'],['zuständig für','responsible for'],['(Passangelegenheiten)','(passport matters)'],['Botschaft der Bundesrepublik Deutschland','Embassy of the Federal Republic of Germany'],['der Bundesrepublik Deutschland','of the Federal Republic of Germany'],[', auch ',', also '],[' (auch ',' (also '],['(u. a. ','(incl. '],['Südkalifornien','Southern California'],['Nordkalifornien','Northern California'],['West- und Ostkap','Western and Eastern Cape'],['Kanaren','Canary Islands']];
const SEG={'an':'arr.','ab':'dep.','bis':'until','eigene Aufgabe':'own task','Notruf':'Emergency','Ankunft':'arrival'};
function seg(s){const ex=EN[s];if(ex!==undefined)return ex;let m;
  if((m=/^(an|ab|bis|Notruf|Ankunft) (.+)$/.exec(s)))return SEG[m[1]]+' '+m[2];
  if((m=/^Eigene Aufgabe$/.exec(s)))return 'Own task';
  for(const [re,rep] of RULES){if(!rep)continue;if(re.test(s))return typeof rep==='function'?s.replace(re,rep):s.replace(re,rep);}
  return s;}
function tr(s){if(!s)return s;const ex=EN[s];if(ex!==undefined)return ex;
  for(const [re,rep] of RULES){if(!rep)continue;if(re.test(s))return typeof rep==='function'?s.replace(re,rep):s.replace(re,rep);}
  let out=s;if(s.includes(' · '))out=s.split(' · ').map(seg).join(' · ');
  for(const [a,b] of PHRASES)if(out.includes(a))out=out.split(a).join(b);
  return out;}
root.RA_t=tr;

/* ---------- DOM übersetzen ---------- */
const SKIP='script,style,textarea,input,select option[data-user],.note,.em-pre,.de-text,.diary-text,[data-no-i18n],[contenteditable]';
const done=new WeakMap();
function textNode(n){const p=n.parentElement;if(!p||p.closest(SKIP))return;const v=n.nodeValue;if(!v||!/[A-Za-zÄÖÜäöüß]/.test(v))return;if(done.get(n)===v)return;
  const lead=v.match(/^\s*/)[0],trail=v.match(/\s*$/)[0],core=v.trim();const t=tr(core);if(t!==core){const nv=lead+t+trail;done.set(n,nv);n.nodeValue=nv;}else done.set(n,v);}
const ATTRS=['placeholder','title','aria-label'];
function el(e){if(e.closest&&e.closest('[data-no-i18n]'))return;for(const a of ATTRS){const v=e.getAttribute&&e.getAttribute(a);if(v){const k=v.replace(/\s+/g,' ').trim(),t=tr(k);if(t!==k)e.setAttribute(a,t);}}}
function walk(root0){if(root0.nodeType===3){textNode(root0);return;}if(root0.nodeType!==1)return;el(root0);const w=document.createTreeWalker(root0,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n;while((n=w.nextNode())){if(n.nodeType===3)textNode(n);else el(n);}}
let scheduled=null;const queue=new Set();
function flush(){scheduled=null;const items=[...queue];queue.clear();for(const n of items)if(n.isConnected!==false)walk(n);}
const mo=new MutationObserver(list=>{for(const m of list){if(m.type==='characterData')queue.add(m.target);else if(m.type==='attributes')queue.add(m.target);else for(const n of m.addedNodes)queue.add(n);}if(!scheduled)scheduled=Promise.resolve().then(flush);});
function start(){document.title=tr(document.title);walk(document.body);mo.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:ATTRS});}
if(document.body)start();else document.addEventListener('DOMContentLoaded',start);
/* Dialoge von window.confirm/alert gibt es in der App nicht; Meldungen laufen über #toast und #confirm-dialog (DOM). */
